// The TourGraph Worker: one Worker serves the site and the API.
// Routing (redirects, API vs pages) lives in src/server/route.ts.
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as nextHandler } from "./.open-next/worker.js";
import { route } from "./src/server/route";
import type { Env } from "./src/server/api/env";

export default {
  fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    return route(request, env, ctx, (req, e, c) => nextHandler.fetch(req, e, c));
  },
} satisfies ExportedHandler<Env>;
